import{_ as e,H as t,f as B,i}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"春节特别放送（三）-我的学习资料和工具","description":"","frontmatter":{},"headers":[{"level":2,"title":"做笔记：形成理论体系","slug":"做笔记-形成理论体系","link":"#做笔记-形成理论体系","children":[]},{"level":2,"title":"用正确的方法找学习资料","slug":"用正确的方法找学习资料","link":"#用正确的方法找学习资料","children":[]},{"level":2,"title":"做中学，学中做","slug":"做中学-学中做","link":"#做中学-学中做","children":[]}],"relativePath":"网络排查案例课/春节特别放送（三）-我的学习资料和工具.md","filePath":"网络排查案例课/春节特别放送（三）-我的学习资料和工具.md","lastUpdated":1795563497000}'),a={name:"网络排查案例课/春节特别放送（三）-我的学习资料和工具.md"};function n(p,E,s,A,l,r){return t(),B("div",null,[...E[0]||(E[0]=[i('<h1 id="春节特别放送-三-我的学习资料和工具" tabindex="-1">春节特别放送（三）-我的学习资料和工具 <a class="header-anchor" href="#春节特别放送-三-我的学习资料和工具" aria-label="Permalink to &quot;春节特别放送（三）-我的学习资料和工具&quot;">​</a></h1><p>你好，我是胜辉。今天是正月初二，过年好啊，春节玩得还开心吗？</p><p>在之前的课程中，我发现有不少同学啊，都在问我学习相关的话题，比如说：</p><ul><li><p>能不能介绍下老师是怎么学习的？</p></li><li><p>老师你有没有推荐学习 TCP/IP 的书单？</p></li><li><p>我是 Java 工程师，怎样可以在网络排查方面快速入门呢？</p></li></ul><p>所以趁着这个机会呢，我想来跟你聊聊“学习”这个老生常谈的话题。</p><p>其实，极客时间上的牛人太多了，在学习上呢，可能都比我更有经验，也更有成就，那我这里就抛砖引玉吧，一点小小的总结和回顾。如果能帮到你一点点，让你在这个新春时节里觉得有一丝收获，那我会跟你一样开心。</p><h2 id="做笔记-形成理论体系" tabindex="-1">做笔记：形成理论体系 <a class="header-anchor" href="#做笔记-形成理论体系" aria-label="Permalink to &quot;做笔记：形成理论体系&quot;">​</a></h2><p>你有没有发现，当你刚读完一本书的时候，印象还是挺深的，也觉得在这块领域里学到了不少。但是随着时间的推移，对这些知识的印象逐渐模糊，最好笑的是，有时候自己甚至会怀疑：这个技术挺难懂的，也没什么印象了，难道真的是我以前学过的东西吗？</p><p>造成这个问题的原因有很多，我觉得其中比较重要的原因，是没有做好笔记。人接收信息的渠道有很多种，比如听说读写，比如实践操作等等。那其中，写应该是比较容易做到的，所以我也挺早就养成了记笔记的习惯。</p><p>最早我是在笔记本电脑上直接记录文档，比如用 Windows 的记事本，或者 Word 文档。当然，它们的缺点也显而易见：在这个移动办公的时代，文档不能在手机等移动设备上查看和编辑，真是一大缺憾。</p><p>所以这几年，我就以在线笔记类 App 为主了，我也用了好几种 App，包括印象笔记、有道云笔记、石墨笔记等等。这些 App 都支持电脑端和手机端，基本上到哪儿都能看笔记或者编辑笔记，十分方便。可以说是让学习深度“侵入”到我的生活中了，但我也乐在其中。看一点笔记，又多懂了一点，以后也可以忘得少一点，这个投入，值得。</p><p>就以印象笔记（国外版叫 Evernote）为例，你可以在笔记本、手机、iPad 等终端上安装它，然后多设备同步。出门在外，只要你手机上有印象笔记，就可以继续学习。特别是它的Markdown 笔记支持代码格式，在阅读一些片段代码的时候很有用。另外，它还有个浏览器插件，当你看到感兴趣的网页时，你就用这个插件把内容给保存为笔记，非常实用。比如像下面这样，我可以把网页中的文稿部分，单独保存为一篇笔记，以后就可以在印象笔记中查看它了：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E6%2598%25A5%25E8%258A%2582%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589-%25E6%2588%2591%25E7%259A%2584%25E5%25AD%25A6%25E4%25B9%25A0%25E8%25B5%2584%25E6%2596%2599%25E5%2592%258C%25E5%25B7%25A5%25E5%2585%25B7/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E6%2598%25A5%25E8%258A%2582%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589-%25E6%2588%2591%25E7%259A%2584%25E5%25AD%25A6%25E4%25B9%25A0%25E8%25B5%2584%25E6%2596%2599%25E5%2592%258C%25E5%25B7%25A5%25E5%2585%25B7/1.png" alt=""></a></p><p>思维导图也是一类比较有用的学习工具。很多知识未必适合用文档或者表格来做精确的整理，但用思维导图来概括和记录，却更加随性、灵活。我一般在电脑上用 XMind。比如下面就是我学习 Envoy 时候梳理的思维导图：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E6%2598%25A5%25E8%258A%2582%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589-%25E6%2588%2591%25E7%259A%2584%25E5%25AD%25A6%25E4%25B9%25A0%25E8%25B5%2584%25E6%2596%2599%25E5%2592%258C%25E5%25B7%25A5%25E5%2585%25B7/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E6%2598%25A5%25E8%258A%2582%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589-%25E6%2588%2591%25E7%259A%2584%25E5%25AD%25A6%25E4%25B9%25A0%25E8%25B5%2584%25E6%2596%2599%25E5%2592%258C%25E5%25B7%25A5%25E5%2585%25B7/2.png" alt=""></a></p><p>我觉得，用思维导图的好处之一就是，如果要找某个知识点，很容易从中心点“顺藤摸瓜”找到它。当然好处也不止于此，思维导图的本质，是利用了人的大脑在接收信息方面的特点：大脑对图形的记忆效率远远超过文字，通过思维导图，这些知识从文字变成了“树枝图像”，可以更加深刻地印到大脑里。</p><p>我在学习一个新领域的知识的时候，经常会新建一个思维导图文件，然后不断往里添加知识的枝干，之后要复习的时候，一眼就能看到这个体系的脉络，确实很有帮助。除了 XMind，国内有个叫 MindMaster 的思维导图产品也不错。</p><p>当然，你在工作中同样可以使用思维导图。比如我几年前做的一个比较大的项目，涉及因素众多，一开始我就是用思维导图把各个方面摸清楚的。对着思维导图，我比较容易地抓到了问题的关键，之后推进起来就比较容易了。推荐你也可以试试。</p><h2 id="用正确的方法找学习资料" tabindex="-1">用正确的方法找学习资料 <a class="header-anchor" href="#用正确的方法找学习资料" aria-label="Permalink to &quot;用正确的方法找学习资料&quot;">​</a></h2><p>现在这个时代，知识爆炸乃至泛滥，我们在网上随便一搜，可能正确的和错误的知识各占一半，这种惊人的比例，让我们不得不认真审视学习资料来源的问题。有时候找不到信息还算好的，就怕找到的是错误的信息，浪费时间不说，还让错误的知识占据了大脑，那正确的知识就进不来了。所以，在寻找学习资料方面，我的建议有这么几个：</p><ul><li>英文原版</li></ul><p>咱们最好加强一下英文，然后阅读原版书籍。这倒不是否认国内翻译者的贡献，而是相对来说，原版的意思会更加贴近原意，然后时效性也更强一点。甚至有些不错的书，未必会有中文译本，特别是一些技术论文，那你要等待中译版几乎是不可能了。你不能总是期望有“野生翻译君”来帮你。</p><p>其实，技术类的英文不是太复杂，一旦熟悉了技术名词就会容易许多。再加上我们学习的编程语言也都是英文的，我想你基础再差也不会差到哪里去，所以还是要多一点信心，只要你愿意去尝试，阅读英文技术文章或者书籍都不是难事。从它的收效来说，你的“投资”绝对值得。</p><ul><li>要读经典</li></ul><p>现在知识碎片化的趋势越来越明显，不可否认，有时候一小段文字也能给我们不少启迪。不过，要在自己头脑里构建一个扎实并且全面的技术蓝图，还是离不开对经典的研读。</p><p>就拿 TCP/IP 来说，我还是推荐经典的 Richard Stevens 等人写就的《TCP/IP 详解》，开发的同学可以看《UNIX 网络编程》。在大多数情况下，读《TCP/IP 详解》第一卷应该就满足日常排查的需求了。在操作系统方面，你也可以读一下《Linux 系统编程》，作者是写过多本技术畅销书的 Robert Love，他本人也还年轻，是一名八零后。</p><p>不过，如果你平时开发任务很忙，或者网络基础比较薄弱一点，一下子读大部头确实相对困难，那么你可以选择稍微简单一点的入门书。比如《图解 HTTP》和《图解 TCP/IP》，这两本书的作者都来自日本，用了比较多的示意图来展示知识点。这跟我前面谈到的思维导图就很类似，图形会给大脑留下更加深刻的印象，所以用这两本来入门也是不错的选择。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E6%2598%25A5%25E8%258A%2582%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589-%25E6%2588%2591%25E7%259A%2584%25E5%25AD%25A6%25E4%25B9%25A0%25E8%25B5%2584%25E6%2596%2599%25E5%2592%258C%25E5%25B7%25A5%25E5%2585%25B7/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E6%2598%25A5%25E8%258A%2582%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589-%25E6%2588%2591%25E7%259A%2584%25E5%25AD%25A6%25E4%25B9%25A0%25E8%25B5%2584%25E6%2596%2599%25E5%2592%258C%25E5%25B7%25A5%25E5%2585%25B7/3.png" alt=""></a></p><ul><li>要找权威来源</li></ul><p>如果我们随便去网上搜索，可能出来很多个人博客，不少内容是抄来抄去，良莠不齐。我建议你直接到比较权威的站点去查看。比如以 HTTP 协议来说，要了解各种 header 和返回码的规范细节，我建议可以去这里看：HTTP | MDN (mozilla.org) 。</p><ul><li>要读 RFC</li></ul><p>另外一块很大的内容，同时也是很容易把你和其他人拉开差距的地方，就是 RFC 文档。我经常看到，很多人会为了一个技术点争论不休，事实上这个东西就在 RFC 上清清楚楚地写着，只要用心的话，去找到文档仔细读一下就行。也就花一点时间读一下文档，就能收获一个“专业”的对外形象，你应该更有动力了吧？</p><p>另外，RFC 文档一般不是太长，内容精练，基本上没什么废话，所以阅读的投入产出比还是挺高的，这也是我推荐你阅读它的另一个很重要的原因。</p><ul><li>要读源码</li></ul><p>最后一块内容，就是内核源码。这是因为，书相对来说更新起来不是那么及时，看源码可以知道最新的行为。另外，还有两个问题你不得不考虑：</p><ul><li><p>有些情况没有在 RFC 里面规定，那这些情况在现实世界里又是如何运作的呢？</p></li><li><p>RFC 的这些规范，在代码层面是如何具体落实的呢？</p></li></ul><p>比如我们最近遇到的一个小困惑。我们发现，TCP 三次握手里面，第二个报文也就是SYN+ACK，它的 IP ID 居然是 0。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E6%2598%25A5%25E8%258A%2582%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589-%25E6%2588%2591%25E7%259A%2584%25E5%25AD%25A6%25E4%25B9%25A0%25E8%25B5%2584%25E6%2596%2599%25E5%2592%258C%25E5%25B7%25A5%25E5%2585%25B7/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E6%2598%25A5%25E8%258A%2582%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589-%25E6%2588%2591%25E7%259A%2584%25E5%25AD%25A6%25E4%25B9%25A0%25E8%25B5%2584%25E6%2596%2599%25E5%2592%258C%25E5%25B7%25A5%25E5%2585%25B7/4.png" alt=""></a></p><p>我们就直接查 Linux 内核源代码，确认是对端 Linux 自身的行为了。这样的例子有很多。总之，脱离了代码谈网络，总还是会有盲区。</p><h2 id="做中学-学中做" tabindex="-1">做中学，学中做 <a class="header-anchor" href="#做中学-学中做" aria-label="Permalink to &quot;做中学，学中做&quot;">​</a></h2><p>“纸上得来终觉浅”，我们可以在测试环境中，不断把自己学到的知识通过实验进行验证，加深印象。比如，对于 TCP/IP 的各种行为，你就可以一边 curl，一边 tcpdump，观察输出的报文细节，再结合自己学到的理论，看看是否能解释通了？如果还有疑问，那么恭喜你，又可以进步了！人学习的过程，不就是一个不断发现漏洞，不断弥补的过程吗？</p><p>如果在实际工作中遇到网络问题，或者你怀疑是网络引起的问题，那么也是很好的机会。你可以参考我在课程里介绍的步骤，比如做抓包，然后 Wireshark 打开做分析。对着看得见的报文来学习网络协议，这个体验确实比单纯看书或者 RFC 有趣得多，也更容易坚持。这也是我的一个小秘诀，分享给你。</p><p>另外，你也可以参考这么一条学习和实践路线，来逐步深入掌握 TCP/IP 网络知识：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E6%2598%25A5%25E8%258A%2582%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589-%25E6%2588%2591%25E7%259A%2584%25E5%25AD%25A6%25E4%25B9%25A0%25E8%25B5%2584%25E6%2596%2599%25E5%2592%258C%25E5%25B7%25A5%25E5%2585%25B7/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/%25E6%2598%25A5%25E8%258A%2582%25E7%2589%25B9%25E5%2588%25AB%25E6%2594%25BE%25E9%2580%2581%25EF%25BC%2588%25E4%25B8%2589%25EF%25BC%2589-%25E6%2588%2591%25E7%259A%2584%25E5%25AD%25A6%25E4%25B9%25A0%25E8%25B5%2584%25E6%2596%2599%25E5%2592%258C%25E5%25B7%25A5%25E5%2585%25B7/5.png" alt=""></a></p><p>好了，我的学习资料和学习工具，大概就介绍到这里。欢迎你畅所欲言，在留言区里分享出你认为好用的学习方法，相信我们都可以学到一大筐非常好用的工具和资料，我也很期待！</p>',45)])])}const u=e(a,[["render",n]]);export{h as __pageData,u as default};
